    const cycle = findCycle(tasksById);
    throw new CliError(`Dependency cycle: ${cycle!.join(" -> ")}`);
  }

  const timings = new Map<string, Timing>();
  const layerById = new Map<string, number>();
  const pathById = new Map<string, string[]>();
  const layers: string[][] = [];

