  if (args.length === 0) {
    throw new CliError("Missing command. Usage: dependency-planner plan INPUT.json");
  }
  if (args[0] !== "plan") {
    throw new CliError(`Unknown command: ${args[0]}`);
  }
  if (args.length < 2) {
    throw new CliError("Missing input file. Usage: dependency-planner plan INPUT.json");
